 let i=0;const fin=()=>{if(!hablando&&!cancelado){res();return}hablando=false;speakEnd=Date.now();fab.classList.remove('spk');awakeUntil=Date.now()+12000;res();if(quiere&&CFG.hf&&!blocked)setTimeout(start,350)};
