function deptoDe(g,fuzzy){g=norm(g);if(!g)return null;if(EXTRAD[g])return EXTRAD[g];for(const[k,ns]of DIDX())if(ns.includes(g))return k;
 if(fuzzy&&g.length>=4){let best=null,bd=9;for(const[k,ns]of DIDX())for(const n of ns){const lim=n.length>=8?2:n.length>=5?1:0;if(!lim)continue;const d=lv(g,n);if(d<=lim&&d<bd){bd=d;best=k}}return best}return null}
function deptoEn(t,opt){opt=opt||{};const tk=t.split(' ');
 for(const fz of [false,true])for(let n=Math.min(4,tk.length);n>=1;n--)for(let i=0;i+n<=tk.length;i++){const g=tk.slice(i,i+n);if(g.every(w=>SINDEP.has(w)||STOPW.has(w)||COMUN.has(w)))continue;if(n===1&&g[0]==='capital'&&!opt.capital)continue;if(n===1&&g[0].length<4)continue;if(n===1&&(COMUN.has(g[0])||ALIASSET.has(g[0])&&g[0]!=='capital'&&g[0]!=='metan'&&g[0]!=='anta'))continue;const k=deptoDe(g.join(' '),fz);if(k)return{k,i,n}}
 return null}
