function repsDe(k){return personas.filter(p=>!p.homonimoDe).map(p=>[p,p.cargos.find(x=>x.v===1&&(x.p.chamber==='Senado'||x.p.chamber==='Diputados'))]).filter(([p,c])=>c&&mapaKey(c.lugar||c.p.department||'')===k)}
function resumenDepto(k){const C=CENS();if(!C||!C.deptos[k])return DNOM(k)+': todavía no hay datos del Censo cargados.';const g=GEOD()&&GEOD().deptos[k],ks=['poblacion','variacion','densidad','edad_mediana','viv_precarias','agua_red','cloaca','internet','tasa_empleo'];
 const partes=[DNOM(k)+(g&&g.cabecera?', cabecera '+g.cabecera:'')+'.'];ks.forEach((key,i)=>{if(typeof C.deptos[k][key]==='number')partes.push(frase(k,key,i>2))});const rp=repsDe(k);if(rp.length)partes.push('Lo representan '+rp.map(([p,c])=>p.nombre+(c.p.chamber==='Senado'?' en el Senado':' en Diputados')).slice(0,4).join(', ')+'.');return partes.join(' ')}
