function sesga(r){try{if(CFG.local&&'processLocally' in r)r.processLocally=true;if(typeof SpeechRecognitionPhrase!=='undefined'&&'phrases' in r){const W=new Set(['Newar','Milei','Sáenz','Kicillof','Bullrich','Villarruel','Massa','Macri','Zuban Córdoba','Poliarquía','Giacobbe','AtlasIntel','Ipsos','Analogías','Isonomía','Synopsis','Opina Argentina','Hemiciclo','Briefing','Consultoras','Estadísticas','Conexiones','Orán','Tartagal','Cafayate','Metán','Cerrillos']);vocabP().slice(0,400).forEach(v=>{if(v[0].length>=5)W.add(v[0].charAt(0).toUpperCase()+v[0].slice(1))});r.phrases=[...W].slice(0,300).map(x=>new SpeechRecognitionPhrase(x,4))}}catch(e){}}
async function instalaLocal(){try{if(typeof SpeechRecognition==='undefined'||!SpeechRecognition.available)return'Este navegador no ofrece reconocimiento en el dispositivo; sigo usando el servicio normal del navegador.';const o={langs:['es-AR'],processLocally:true};let a=await SpeechRecognition.available(o);if(a==='unavailable'){o.langs=['es'];a=await SpeechRecognition.available(o)}if(a==='available'){CFG.local=1;save();return'Listo: el reconocimiento ahora se hace en tu dispositivo, sin enviar el audio.'}if(a==='downloadable'||a==='downloading'){await SpeechRecognition.install(o);CFG.local=1;save();return'Descargué el paquete de idioma. Desde ahora reconozco en tu dispositivo.'}return'Tu navegador no puede reconocer español en el dispositivo; sigo con el servicio normal.'}catch(e){return'No pude activar el reconocimiento en el dispositivo en este navegador.'}}
function start(){if(!SR){show('','Este navegador no tiene reconocimiento de voz. Usá Chrome, Edge o Safari, o escribí la orden en el cuadro.',false);abrir(true);return}
 if(oyendo||hablando)return;blocked=false;quiere=true;rec=new SR();rec.lang='es-AR';sesga(rec);rec.continuous=!!CFG.hf;rec.interimResults=true;rec.maxAlternatives=5;let hecho=-1;
 rec.onstart=()=>{ui(true);fails=0;estado('escuchando');show('',CFG.hf?'Escucho. Decí «Newar» y tu orden.':'Te escucho…',null);clearTimeout(wd);if(!CFG.hf)wd=setTimeout(()=>{if(oyendo){show('','No escuché nada. Probá de nuevo o escribí la orden.',false);estado('error','silencio');stop()}},12000)};
 rec.onresult=e=>{clearTimeout(wd);for(let i=e.resultIndex;i<e.results.length;i++){const r=e.results[i];if(!r.isFinal){show(r[0].transcript,'…',null);continue}if(i<=hecho)continue;hecho=i;const alts=Array.from(r).map(a=>a.transcript).filter(Boolean);if(!alts.length)continue;
   if(buf.length&&norm(buf[buf.length-1].alts[0])===norm(alts[0]))continue;buf.push({alts,conf:r[0].confidence});clearTimeout(bufT);
   bufT=setTimeout(()=>{const b=buf;buf=[];Promise.resolve(procesar(b)).then(()=>{if(!CFG.hf){quiere=false;try{rec.stop()}catch(x){}}})},CFG.hf?800:450)}};
 rec.onerror=e=>{const c=e.error;if(c==='no-speech'){show('','No escuché nada. Probá de nuevo o escribí la orden.',false);estado('error','silencio')}else if(c==='not-allowed'||c==='service-not-allowed'){blocked=true;quiere=false;CFG.hf=0;estado('error','permiso denegado');show('','El navegador no dio permiso al micrófono. Habilitalo desde el candado de la barra de direcciones, o escribí la orden en el cuadro.',false)}else if(c==='language-not-supported'){fails++;show('','Tu navegador no soporta español de Argentina: pruebo con español general.',false);try{rec.lang='es'}catch(x){}}else if(c==='audio-capture'){blocked=true;quiere=false;show('','No encuentro un micrófono.',false)}else if(c==='network'){fails++;show('','Falló la conexión del servicio de voz del navegador'+(fails>2?'. Probá escribir las órdenes.':'; reintento…'),false);if(fails>4){quiere=false}}};
 rec.onend=()=>{clearTimeout(wd);ui(false);if(!blocked&&$('#nvst')&&$('#nvst').dataset.estado==='escuchando')estado('listo');if(quiere&&CFG.hf&&!blocked&&!hablando)setTimeout(()=>{if(quiere&&!oyendo)start()},fails>2?2500:300)};
 try{rec.start()}catch(e){ui(false)}}
function stop(){quiere=false;clearTimeout(wd);try{rec&&rec.stop()}catch(e){}ui(false);if($('#nvst')&&$('#nvst').dataset.estado==='escuchando')estado('listo')}
